"""Den / Lair art (your painted cave sheet): background, hanging sign, chain, sign icons, stone title plaque, coin box.
img(name) gives the surface; scaled(name, w, h) a cached resized copy."""
import base64
import io
import pygame

# glowing spots painted in lair_bg.png (x, y, radius) in its own pixels: wall torches, then lanterns
LIGHTS = ((570, 40, 48), (1300, 40, 48), (185, 235, 34), (580, 270, 30), (1690, 235, 34), (1745, 580, 30), (1355, 365, 22), (1150, 215, 22))
FIRE_PIT = (415, 742)          # centre of the fire-pit logs in lair_bg.png (the game draws the flames)
HOARD_TOP = (905, 545)         # the peak of the gold pile in lair_bg.png (the player's dragon sleeps here)
PNG = {
  'chain': ('png', ''),
  'coin': ('png', ''),
  'coin_box': ('png', ''),
  'icon_lair_eggs': ('png', ''),
  'icon_lair_enemies': ('png', ''),
  'icon_lair_hatchlings': ('png', ''),
  'icon_lair_hoard': ('png', ''),
  'icon_lair_quests': ('png', ''),
  'icon_lair_roster': ('png', ''),
  'lair_bg': ('jpg', ''),
  'lair_plaque': ('png', ''),
  'sign': ('png', ''),
}
_C = {}


def has(name):
  return name in PNG


def img(name):
  s = _C.get(name)
  if s is None:
    ext, data = PNG[name]
    s = pygame.image.load(io.BytesIO(base64.b64decode(data)), 'art.' + ext)
    try:
      s = s.convert_alpha()
    except Exception:
      pass
    _C[name] = s
  return s


def scaled(name, w, h, smooth=True):
  k = (name, int(w), int(h))
  s = _C.get(k)
  if s is None:
    src = img(name)
    fn = getattr(pygame.transform, 'smoothscale', None) if smooth else None
    try:
      s = (fn or pygame.transform.scale)(src, (max(1, int(w)), max(1, int(h))))
    except Exception:
      s = pygame.transform.scale(src, (max(1, int(w)), max(1, int(h))))
    _C[k] = s
  return s
